differentialEquations.code:
return tokens.map((token) => {
  const hour = ((token.time_hours % 24) + 24) % 24;
  const demand = (hour >= 6.5 && hour < 9)
    ? parameters.morning_peak_demand_lps
    : parameters.night_demand_lps;
  const unrestrictedInflow = token.pump_on ? parameters.pump_rate_lps : 0;
  const inflow = token.pump_on && parameters.vsd_enabled
    ? Math.min(parameters.pump_rate_lps, demand + parameters.vsd_margin_lps)
    : unrestrictedInflow;
  const rawDLevel = ((inflow - demand) / 1000) * 3600 / parameters.storage_m3_per_m;
  const dLevel = (token.level_m >= parameters.reservoir_depth_m && rawDLevel > 0)
    ? 0
    : ((token.level_m <= 0 && rawDLevel < 0) ? 0 : rawDLevel);
  return { level_m: dLevel, time_hours: 1 };
});

